#include <cctype>
#include <deque>
#include <iostream>
#include <map>
#include <optional>
#include <string>
#include <utility>
#include <vector>

struct CalcError
{
    std::string message;
};

static std::string trim(const std::string& s)
{
    std::size_t a = s.find_first_not_of(" \t\r");
    if (a == std::string::npos) return "";
    std::size_t b = s.find_last_not_of(" \t\r");
    return s.substr(a, b - a + 1);
}

static bool isNameStart(char c) { return std::isalpha(static_cast<unsigned char>(c)) || c == '_'; }
static bool isNameChar(char c) { return std::isalnum(static_cast<unsigned char>(c)) || c == '_'; }

static bool validName(const std::string& s)
{
    if (s.empty() || !isNameStart(s[0])) return false;
    for (char c : s)
        if (!isNameChar(c)) return false;
    return true;
}

class Calculator
{
public:
    long long evaluate(const std::string& text) const
    {
        std::vector<long long> values;
        std::vector<char> ops;
        bool expectValue = true;

        auto precedence = [](char op) { return op == 'u' ? 3 : (op == '*' || op == '/' || op == '%') ? 2 : 1; };
        auto apply = [&] {
            char op = ops.back();
            ops.pop_back();
            if (op == 'u')
            {
                values.back() = -values.back();
                return;
            }
            long long b = values.back();
            values.pop_back();
            long long a = values.back();
            values.pop_back();
            if ((op == '/' || op == '%') && b == 0) throw CalcError{ "division by zero" };
            switch (op)
            {
            case '+': values.push_back(a + b); break;
            case '-': values.push_back(a - b); break;
            case '*': values.push_back(a * b); break;
            case '/': values.push_back(a / b); break;
            default: values.push_back(a % b); break;
            }
        };

        for (std::size_t i = 0; i < text.size(); ++i)
        {
            char c = text[i];
            if (std::isspace(static_cast<unsigned char>(c))) continue;

            if (std::isdigit(static_cast<unsigned char>(c)))
            {
                if (!expectValue) throw CalcError{ "expected an operator" };
                std::size_t start = i;
                while (i < text.size() && std::isdigit(static_cast<unsigned char>(text[i]))) ++i;
                std::string digits = text.substr(start, i - start);
                --i;
                if (digits.size() > 18) throw CalcError{ "number too big" };
                values.push_back(std::stoll(digits));
                expectValue = false;
            }
            else if (isNameStart(c))
            {
                if (!expectValue) throw CalcError{ "expected an operator" };
                std::size_t start = i;
                while (i < text.size() && isNameChar(text[i])) ++i;
                std::string name = text.substr(start, i - start);
                --i;
                auto it = vars_.find(name);
                if (it == vars_.end()) throw CalcError{ "unknown variable '" + name + "'" };
                values.push_back(it->second);
                expectValue = false;
            }
            else if (c == '(')
            {
                if (!expectValue) throw CalcError{ "expected an operator" };
                ops.push_back('(');
            }
            else if (c == ')')
            {
                bool open = false;
                for (char op : ops)
                    if (op == '(') open = true;
                if (!open) throw CalcError{ "unexpected ')'" };
                if (expectValue) throw CalcError{ "expected a value" };
                while (ops.back() != '(') apply();
                ops.pop_back();
            }
            else if (c == '+' || c == '-' || c == '*' || c == '/' || c == '%')
            {
                if (expectValue)
                {
                    if (c != '-') throw CalcError{ "expected a value" };
                    ops.push_back('u');
                    continue;
                }
                while (!ops.empty() && ops.back() != '(' && precedence(ops.back()) >= precedence(c)) apply();
                ops.push_back(c);
                expectValue = true;
            }
            else
            {
                throw CalcError{ std::string("unexpected character '") + c + "'" };
            }
        }

        if (expectValue) throw CalcError{ "expected a value" };
        while (!ops.empty())
        {
            if (ops.back() == '(') throw CalcError{ "missing closing bracket" };
            apply();
        }
        return values.back();
    }

    // Runs one command and returns the lines it prints.
    std::vector<std::string> run(const std::string& line)
    {
        try
        {
            if (line == "undo") return { undo() };
            if (line == "history") return { history() };
            if (line == "vars") return vars();
            if (line == "let" || line.rfind("let ", 0) == 0) return { let(line.substr(3)) };
            long long value = evaluate(line);
            remember(value);
            return { std::to_string(value) };
        }
        catch (const CalcError& e)
        {
            return { "error: " + e.message };
        }
    }

private:
    std::string let(const std::string& rest)
    {
        std::size_t eq = rest.find('=');
        if (eq == std::string::npos) throw CalcError{ "usage: let <name> = <expression>" };
        std::string name = trim(rest.substr(0, eq));
        if (!validName(name)) throw CalcError{ "usage: let <name> = <expression>" };
        long long value = evaluate(rest.substr(eq + 1));

        auto it = vars_.find(name);
        undo_.push_back({ name, it == vars_.end() ? std::nullopt : std::optional<long long>(it->second) });
        vars_[name] = value;
        remember(value);
        return name + " = " + std::to_string(value);
    }

    std::string undo()
    {
        if (undo_.empty()) return "nothing to undo";
        auto [name, previous] = undo_.back();
        undo_.pop_back();
        if (previous) vars_[name] = *previous; else vars_.erase(name);
        return "undone: let " + name;
    }

    std::string history() const
    {
        if (history_.empty()) return "history: empty";
        std::string out = "history: ";
        for (std::size_t i = 0; i < history_.size(); ++i) out += (i ? ", " : "") + std::to_string(history_[i]);
        return out;
    }

    std::vector<std::string> vars() const
    {
        if (vars_.empty()) return { "no variables" };
        std::vector<std::string> out;
        for (const auto& [name, value] : vars_) out.push_back(name + " = " + std::to_string(value));
        return out;
    }

    void remember(long long value)
    {
        history_.push_back(value);
        if (history_.size() > 5) history_.pop_front();
    }

    std::map<std::string, long long> vars_;
    std::vector<std::pair<std::string, std::optional<long long>>> undo_;
    std::deque<long long> history_;
};

int main()
{
    Calculator calc;
    std::string line;
    while (std::getline(std::cin, line))
    {
        line = trim(line);
        if (line.empty()) continue;
        if (line == "quit") break;
        for (const std::string& out : calc.run(line)) std::cout << out << '\n';
    }
}
